function edgePath(e,offset=0){const a=node(e.source),b=node(e.target);if(!a||!b)return '';const ax=a.x+90,ay=a.y+33,bx=b.x+90,by=b.y+33,dx=bx-ax,dy=by-ay;if(Math.abs(dx)+Math.abs(dy)<1)return '';if(e.style==='curved'){const len=Math.hypot(dx,dy),px=-dy/len,py=dx/len,sx=ax+dx*.28+px*offset,sy=ay+dy*.28+py*offset,ex=ax+dx*.72+px*offset,ey=ay+dy*.72+py*offset;return `M ${ax} ${ay} Q ${sx} ${sy} ${ex} ${ey} T ${bx} ${by}`}if(Math.abs(dx)>=Math.abs(dy)){const dir=dx>0?1:-1,sx=a.x+(dir>0?180:0),tx=b.x+(dir>0?0:180),sy=ay+offset,ty=by+offset,mid=(sx+tx)/2,clearance=36+Math.abs(offset)*.6,side=Math.sign(offset||1),mx=mid+offset;let path=`M ${sx} ${sy} L ${mx} ${sy}`;if(Math.abs(ty-sy)>2*clearance)path+=` L ${mx} ${sy+side*clearance} L ${mx} ${ty-side*clearance}`;return path+` L ${mx} ${ty} L ${tx} ${ty}`}const dir=dy>0?1:-1,sy=a.y+(dir>0?66:0),ty=b.y+(dir>0?0:66),sx=ax+offset,tx=bx+offset,mid=(sy+ty)/2,clearance=36+Math.abs(offset)*.6,side=Math.sign(offset||1);let path=`M ${sx} ${sy} L ${sx} ${mid+side*clearance}`;if(Math.abs(tx-sx)>2*clearance)path+=` L ${sx+side*clearance} ${mid+side*clearance} L ${tx-side*clearance} ${mid+side*clearance}`;return path+` L ${tx} ${mid+side*clearance} L ${tx} ${ty}`}
