function nodeRole(n){const d=device(n.device_id),v=`${d?.metadata?.zone||''} ${d?.metadata?.role||''} ${n.group||''} ${d?.metadata?.function||''} ${n.kind||''} ${d?.device_type||''} ${d?.name||''}`.toLowerCase();if(/internet|\bwan\b|cloud/.test(v))return'WAN';if(/firewall|security|sophos/.test(v))return'Firewall';if(/core/.test(v))return'Core';if(/distribution|\bdist\b/.test(v))return'Distribution';if(/access/.test(v))return'Access';if(/dmz/.test(v))return'DMZ';if(/management|mgmt/.test(v))return'Management';if(/server|storage|virtualization|database/.test(v))return'Server Farm';if(/vlan|subnet/.test(v))return'Network';return d?.metadata?.zone||d?.metadata?.location||null}
