function groupsMarkup(){const groups=new Map(),layers=new Map();for(const n of doc().nodes){if(n.group){if(!groups.has(n.group))groups.set(n.group,[]);groups.get(n.group).push(n)}const role=nodeRole(n);if(role){if(!layers.has(role))layers.set(role,[]);layers.get(role).push(n)}}const palette={WAN:['#eff6ff','#93c5fd','#1d4ed8'],Firewall:['#fef2f2','#fca5a5','#b91c1c'],Core:['#eff6ff','#60a5fa','#1d4ed8'],Distribution:['#f0f9ff','#7dd3fc','#0369a1'],Access:['#ecfdf5','#6ee7b7','#047857'],DMZ:['#fffbeb','#fcd34d','#b45309'],Management:['#f5f3ff','#c4b5fd','#6d28d9'],'Server Farm':['#f0fdf4','#86efac','#15803d'],Network:['#eff6ff','#93c5fd','#2563eb']};const grouped=[...groups].map(([name,ns])=>{const b=bounds(ns);return `<g data-group="${esc(name)}"><rect x="${b.x+25}" y="${b.y+15}" width="${Math.max(40,b.w-50)}" height="${Math.max(45,b.h-30)}" rx="16" fill="#2563eb08" stroke="#94a3b8" stroke-dasharray="5 5"/><text x="${b.x+40}" y="${b.y+34}" fill="#64748b" font-size="11">${esc(name)}</text></g>`}).join('');const zoned=[...layers].map(([name,ns])=>{const b=bounds(ns),c=palette[name]||['#f8fafc','#cbd5e1','#475569'];return `<g class="st-layer" pointer-events="none" data-layer="${esc(name)}"><rect x="${b.x+10}" y="${b.y+2}" width="${Math.max(65,b.w-20)}" height="${Math.max(64,b.h-4)}" rx="12" fill="${c[0]}" stroke="${c[1]}"/><text x="${b.x+24}" y="${b.y+24}" fill="${c[2]}" font-size="12" font-weight="700">${esc(name)} · ${ns.length}</text></g>`}).join('');return zoned+grouped}
