async function loadLiveTopology(dependencies=Promise.resolve()){const [topology,mapping]=await Promise.all([fetch('/api/discovery/topology',{credentials:'same-origin'}),request('/port-mapping')]);if(!topology.ok)throw Error('Không tải được topology discovery');const raw=await topology.json();await dependencies;S.live.topology=raw;S.live.mapping=mapping;const hybrid=(S.inventory||[]).filter(d=>d.hybrid_identity_id);for(const d of hybrid){const h=mapping.ha?.devices.find(h=>h.canonical_id===d.id);if(h?.network_device_id!=null&&h.network_device_id!==d.id)S.live.topology.nodes=S.live.topology.nodes.filter(n=>Number(n.device_id)!==h.network_device_id);let n=S.live.topology.nodes.find(n=>Number(n.device_id)===d.id);if(n)Object.assign(n,d,{id:'d:'+d.id,device_id:d.id});else S.live.topology.nodes.push({...d,id:'d:'+d.id,device_id:d.id,managed:true,layer:'firewall'});}layoutLiveTopology(false);if(typeof IPAMTopologyV2!=='undefined'&&!v2manual&&!v2saved){const found=S.diagrams.find(d=>d.title==='Network Topology V2 · Shared layout');if(found){v2saved=await request('/diagrams/'+found.id);v2SavedLayoutOptions(v2saved.document);for(const n of v2saved.document.nodes)if(S.live.positions[n.id])S.live.positions[n.id]={x:n.x,y:n.y};v2manual=true}}const available=new Set((S.live.topology.nodes||[]).filter(n=>n.device_id!=null).map(n=>Number(n.device_id)));if(!available.has(Number(S.live.selectedDevice))){const candidates=(S.live.topology.nodes||[]).filter(n=>n.device_id!=null&&/switch|nexus|catalyst|sg350/i.test(`${n.device_type||''} ${n.name||''}`));candidates.sort((a,b)=>liveNodeLayer(a)-liveNodeLayer(b)||String(a.name||'').localeCompare(String(b.name||'')));S.live.selectedDevice=Number(candidates[0]?.device_id)||null;S.live.selectedPort=null}S.live.inspectorDirty=true;liveLoadedAt=Date.now();if(S.live.selectedDevice&&v2opt.panel){try{const result=await request('/inventory/'+S.live.selectedDevice+'/ports');S.ports=result.ports||[];S.portProfile=result.hardware_profile||null}catch{S.ports=[];S.portProfile=null}}}
function liveNodeLayer(n){const d=device(n.device_id),role=String(d?.metadata?.role||d?.metadata?.function||d?.metadata?.zone||'').toLowerCase();if(/firewall|security/.test(role))return 0;if(/core/.test(role))return 1;if(/distribution|dist/.test(role))return 2;if(/access/.test(role))return 3;if(/server|storage|virtual/.test(role))return 4;return ({firewall:0,core:1,distribution:2,access:3,server:4,other:2})[String(n.layer||'other').toLowerCase()]??2}
function layoutLiveTopology(force=false){if(typeof IPAMTopologyV2!=='undefined')return v2layout(force);const nodes=(S.live.topology?.nodes||[]).filter(n=>n.device_id!=null),links=(S.live.mapping?.links||[]).filter(l=>l.target_device_id&&l.source_device_id);if(!nodes.length)return;const byId=new Map(nodes.map(n=>[Number(n.device_id),n]));const adjacency=new Map(nodes.map(n=>[Number(n.device_id),new Set()]));for(const l of links){adjacency.get(Number(l.source_device_id))?.add(Number(l.target_device_id));adjacency.get(Number(l.target_device_id))?.add(Number(l.source_device_id))}const ranks=new Map(nodes.map(n=>[n.id,liveNodeLayer(n)]));for(const n of nodes){if(n.layer!=='other'||device(n.device_id)?.metadata?.role||device(n.device_id)?.metadata?.function||device(n.device_id)?.metadata?.zone)continue;let q=[Number(n.device_id)];const seen=new Set(q);let distance=0,found=null;while(q.length&&distance<4&&!found){const next=[];for(const did of q)for(const peer of adjacency.get(did)||[]){if(seen.has(peer))continue;seen.add(peer);next.push(peer);const p=byId.get(peer);if(p&&p.layer!=='other'){found=liveNodeLayer(p);break}}q=next;distance++}if(found!==null)ranks.set(n.id,Math.min(4,found+(found<2?1:found===2?1:0)))}const buckets=new Map();for(const n of nodes){const rank=ranks.get(n.id);if(!buckets.has(rank))buckets.set(rank,[]);buckets.get(rank).push(n)}const nextPositions={},columns=Math.min(32,Math.max(1,Math.ceil(Math.sqrt(nodes.length*1.5))));let rowTop=70;for(const [,items] of [...buckets].sort((a,b)=>a[0]-b[0])){items.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));const rowCount=Math.max(1,Math.ceil(items.length/columns));items.forEach((n,i)=>{const saved=!force&&n.position;if(saved&&Number.isFinite(saved.x)&&Number.isFinite(saved.y))nextPositions[n.id]={x:saved.x,y:saved.y};else nextPositions[n.id]={x:90+(columns-Math.min(columns,items.length-Math.floor(i/columns)*columns))*115+(i%columns)*230,y:rowTop+Math.floor(i/columns)*120}});rowTop+=rowCount*120+30}S.live.positions=nextPositions;}
function liveBounds(){if(typeof IPAMTopologyV2!=='undefined'&&v2geometry)return v2bounds();const p=Object.values(S.live.positions);if(!p.length)return{x:0,y:0,w:1100,h:800};const xs=p.map(x=>x.x),ys=p.map(x=>x.y);return{x:Math.min(...xs)-35,y:Math.min(...ys)-45,w:Math.max(...xs)-Math.min(...xs)+260,h:Math.max(...ys)-Math.min(...ys)+170}}
function liveFit(){const svg=$('#st-live-canvas');if(!svg)return;const b=liveBounds(),r=svg.getBoundingClientRect(),scale=Math.max(.035,Math.min(1.25,Math.min((r.width-50)/b.w,(r.height-70)/b.h)));S.live.transform={scale,x:(r.width-b.w*scale)/2-b.x*scale,y:(r.height-b.h*scale)/2-b.y*scale};liveGraph()}
function liveDisplayLinks(){const saved=S.live.mapping?.links||[],pairs=new Set(saved.map(l=>[Number(l.source_device_id),Number(l.target_device_id)].sort((a,b)=>a-b).join(':'))),extra=[];if(typeof IPAMTopologyV2!=='undefined'){const seen=new Set();for(const o of S.live.mapping?.unresolved||[]){const a=Number(o.device_id),b=Number(o.remote_device_id);if(!a||!b||a===b||pairs.has([a,b].sort((x,y)=>x-y).join(':')))continue;const id='discovered:logical:'+a+':'+String(o.local_port)+':'+b+':'+String(o.remote_port);if(seen.has(id))continue;seen.add(id);extra.push({id,source_device_id:a,target_device_id:b,source_port:o.local_port||'Unknown',target_port:o.remote_port||'Unknown',status:'UNKNOWN_UNVERIFIED',link_type:'LOGICAL_OBSERVATION',logical_observation:true,source:'DISCOVERY',protocols:[o.protocol],last_seen:o.last_seen,evidence_count:1})}return [...saved,...extra]}for(const e of S.live.topology?.links||[]){if(e.manual||!/^d:\d+$/.test(e.source)||!/^d:\d+$/.test(e.target))continue;const a=Number(e.source.slice(2)),b=Number(e.target.slice(2));if(a===b||pairs.has([a,b].sort((x,y)=>x-y).join(':')))continue;extra.push({id:'discovered:logical:'+e.id,source_device_id:a,target_device_id:b,source_port:e.local_port&&e.local_port!=='—'?e.local_port:'Unknown',target_port:e.remote_port&&e.remote_port!=='—'?e.remote_port:'Unknown',status:'UNKNOWN_UNVERIFIED',link_type:'LOGICAL_OBSERVATION',protocol:e.protocol,last_seen:e.last_seen,observation_count:e.link_count||1,logical_observation:true,source:'DISCOVERY',evidence_count:e.link_count||1})}return [...saved,...extra]}
function liveEdges(){const links=liveDisplayLinks().filter(l=>l.target_device_id&&l.source_device_id&&S.live.positions['d:'+l.source_device_id]&&S.live.positions['d:'+l.target_device_id]);const pairs=new Map();for(const l of links){const ids=[Number(l.source_device_id),Number(l.target_device_id)].sort((a,b)=>a-b),key=ids.join(':');if(!pairs.has(key))pairs.set(key,{id:'pair:'+key,a:'d:'+ids[0],b:'d:'+ids[1],links:[]});pairs.get(key).links.push(l)}if(S.live.viewMode==='logical')return [...pairs.values()].map(p=>({...p,status:p.links.some(l=>l.status==='CONFLICT')?'CONFLICT':p.links.some(l=>l.status==='ONE_SIDED')?'ONE_SIDED':p.links.some(l=>l.logical_observation)?'UNKNOWN_UNVERIFIED':p.links.every(l=>l.status==='MANUAL')?'MANUAL':'CONFIRMED'}));const out=[];for(const p of pairs.values()){const shown=S.live.viewMode==='physical'?p.links.filter(link=>link.link_type!=='PORT_CHANNEL'&&!link.logical_observation):p.links;shown.forEach((link,lane)=>out.push({id:link.id,a:p.a,b:p.b,link,lane,laneCount:shown.length}))}return out}
function liveEdgeRoute(a,b,offset){const sameRow=Math.abs(a.y-b.y)<95;if(sameRow){const left=a.x<=b.x?a:b,right=left===a?b:a,y=left.y+28+offset*.35;if(right.x-left.x<260)return `M ${left.x+165} ${y} L ${right.x+25} ${y}`;const laneY=Math.min(a.y,b.y)-9-Math.abs(offset);return `M ${left.x+95} ${left.y+3} L ${left.x+95} ${laneY} L ${right.x+95} ${laneY} L ${right.x+95} ${right.y+3}`}const top=a.y<b.y?a:b,bottom=top===a?b:a,sourceX=top.x+165,sourceY=top.y+28,targetX=bottom.x+25,targetY=bottom.y+28,escapeX=top.x+205+offset,entryX=bottom.x-15+offset,mid=bottom.y-16+offset*.3;return `M ${sourceX} ${sourceY} L ${escapeX} ${sourceY} L ${escapeX} ${mid} L ${entryX} ${mid} L ${entryX} ${targetY} L ${targetX} ${targetY}`}

function liveDeviceGlyph(n){const type=`${n.layer||''} ${n.device_type||''}`.toLowerCase();if(/firewall|sophos/.test(type))return `<g class="st-live-device-glyph" transform="translate(34 0)" aria-hidden="true"><path d="M0 12 18 1H116L132 12V44H0Z" fill="#3976BD" stroke="#8CB9DA"/><path d="M0 12H132L116 1H18Z" fill="#8CB9DA"/><path d="M116 12 132 12V44H116Z" fill="#0067A0"/><path d="M0 12H116M0 28H116M20 12V28M58 12V28M95 12V28M38 28V44M77 28V44" stroke="#EAF4FB" stroke-width="2"/><circle cx="123" cy="35" r="2" fill="#94A3B8"/></g>`;if(/server|storage/.test(type))return `<g class="st-live-device-glyph" transform="translate(62 0)" aria-hidden="true">${[0,15,30].map(y=>`<rect x="0" y="${y}" width="66" height="13" rx="3" fill="#125f91" stroke="#9AB9E4"/><circle cx="8" cy="${y+6}" r="2" fill="#B3D6C9"/><path d="M20 ${y+6}H56" stroke="#a8e6ff"/>`).join('')}</g>`;const core=/core|nexus/.test(type);return `<g class="st-live-device-glyph" transform="translate(25 0)" aria-hidden="true"><path d="M0 13 20 0H124L140 13V44H0Z" fill="${core?'#087ab5':'#087e9d'}" stroke="#38bdf8" stroke-width="1.4"/><path d="M0 13 20 0H124L140 13Z" fill="${core?'#24b8f0':'#2dc5cf'}"/><path d="M124 13H140V44H124Z" fill="#06466a"/><rect x="2" y="15" width="121" height="27" rx="2" fill="#093e63"/>${[0,1].map(row=>[0,1,2,3,4].map(col=>`<rect x="${10+col*17}" y="${19+row*12}" width="12" height="7" rx="1" fill="#06263d" stroke="#7dd3fc" stroke-width=".7"/><path d="M${12+col*17} ${21+row*12}h8" stroke="#c9efff" stroke-width="1.5"/>`).join('')).join('')}<path d="M103 19v16m-7-8h14m-12-6 10 12m-10 0 10-12" stroke="#e0faff" stroke-width="2"/><circle cx="116" cy="37" r="1.5" fill="#3dffc4"/></g>`}

function liveNodeMarkup(n){const p=S.live.positions[n.id]||{x:80,y:80},d=device(n.device_id),selected=Number(S.live.selectedDevice)===Number(n.device_id),link=liveDisplayLinks().find(l=>l.id===S.live.selectedLink),related=link&&[link.source_device_id,link.target_device_id].some(id=>Number(id)===Number(n.device_id)),layer=String(n.layer||'other');return `<g class="st-live-node ${selected?'selected':''} ${related?'related':''}" data-live-node="${esc(n.id)}" transform="translate(${p.x} ${p.y})" tabindex="0" role="button" aria-label="${esc(n.name)}"><rect width="190" height="96" rx="10"/>${liveDeviceGlyph(n)}<text class="st-live-name" x="95" y="57" text-anchor="middle">${esc(String(n.name||'Unknown').slice(0,24))}</text><text class="st-live-ip" x="95" y="74" text-anchor="middle">${esc(d?.management_ip||n.management_ip||'IP chưa xác định')}</text><text class="st-live-type" x="95" y="90" text-anchor="middle">${esc(String(n.device_type||n.platform||layer).slice(0,30))}</text><circle cx="164" cy="22" r="4" class="st-live-status ${String(n.status).toLowerCase()==='up'?'up':''}"/><title>${esc(`${n.name||'Unknown'} · ${d?.management_ip||n.management_ip||''} · ${n.device_type||''} · ${n.status||'unknown'}`)}</title></g>`}
function liveLinkColor(link){if(link?.logical_observation)return'#0284c7';if(link?.status==='CONFLICT')return'#ef4444';if(link?.status==='ONE_SIDED')return'#f59e0b';if(link?.link_type==='PORT_CHANNEL')return'#ef9c16';const speed=Math.min(Number(link?.source_speed_bps)||0,Number(link?.target_speed_bps)||0);if(speed>=4e10)return'#ff5b76';if(speed>=1e10)return'#22c7ff';if(speed>=1e9)return'#6b9eff';if(link?.status==='CONFIRMED')return'#10b981';if(link?.status==='MANUAL')return'#9333ea';return'#60a5fa'}
function liveGraph(){if(typeof IPAMTopologyV2!=='undefined')return v2Graph();const svg=$('#st-live-canvas');if(!svg||!S.live.topology)return;const nodes=(S.live.topology.nodes||[]).filter(n=>n.device_id!=null),edges=liveEdges(),t=S.live.transform;const layers=[['Firewall',0,'#ff6b81','#f43f5e'],['Core',1,'#38a9ff','#1685ef'],['Distribution',2,'#46cfeb','#0891b2'],['Access',3,'#57df9a','#16a36c'],['Servers',4,'#b39bff','#8b5cf6']];const allPositions=nodes.map(n=>S.live.positions[n.id]).filter(Boolean),bandX=Math.min(...allPositions.map(p=>p.x))-30,bandWidth=Math.max(600,Math.max(...allPositions.map(p=>p.x))-bandX+220);const bands=layers.map(([label,rank,fill,stroke])=>{const ns=nodes.filter(n=>liveNodeLayer(n)===rank);if(!ns.length)return'';const ps=ns.map(n=>S.live.positions[n.id]||{x:0,y:0}),x=bandX,y=Math.min(...ps.map(p=>p.y))-40,w=bandWidth,h=Math.max(140,Math.max(...ps.map(p=>p.y))-y+106);return `<g class="st-live-band" data-layer="${label.toLowerCase()}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="16" fill="${fill}" stroke="${stroke}"/><path class="st-live-band-stripe" d="M ${x+16} ${y} H ${x+w-16} Q ${x+w} ${y} ${x+w} ${y+16} V ${y+31} H ${x} V ${y+16} Q ${x} ${y} ${x+16} ${y}Z" fill="${stroke}"/><text x="${x+16}" y="${y+22}" fill="${stroke}" class="st-live-band-title">${label} · ${ns.length}</text></g>`}).join('');const paths=edges.map((e,edgeIndex)=>{const a=S.live.positions[e.a],b=S.live.positions[e.b];if(!a||!b)return'';const offset=e.links?0:((e.lane-(e.laneCount-1)/2)*16),status=e.links?e.status:e.link?.status,detail=e.link||e.links?.[0],color=liveLinkColor({...detail,status}),selected=e.link?.id===S.live.selectedLink||e.links?.some(x=>x.id===S.live.selectedLink),logical=e.links?.length>1;const acx=a.x+95,bcx=b.x+95,acy=a.y+28,bcy=b.y+28,mid=(acy+bcy)/2+offset*.35,path=liveEdgeRoute(a,b,offset+(Math.abs(a.y-b.y)>=95?(edgeIndex%7)*4-12:0)),label=logical?`${e.links.length} links`:`${detail?.source_port||'Unknown'} ↔ ${detail?.target_port||'Unknown'}`,labelX=(acx+bcx)/2;return `<g class="st-live-edge ${selected?'selected':''}" data-live-edge="${esc(e.id)}"><path d="${path}" stroke="${color}" stroke-dasharray="${status==='ONE_SIDED'||status==='UNKNOWN_UNVERIFIED'?'8 6':detail?.link_type==='PORT_CHANNEL'?'5 4':''}"/><path class="st-live-hit" d="${path}"/><g class="st-live-wire-label"><rect x="${labelX-92}" y="${mid-15}" width="184" height="30" rx="8"/><text x="${labelX}" y="${mid+4}" text-anchor="middle">${esc(label)}</text></g><title>${esc(e.links?e.links.map(l=>`${l.source_port} ↔ ${l.target_port} · ${l.status}`).join('\n'):`${e.link.source_port} ↔ ${e.link.target_port} · ${e.link.status}`)}</title></g>`}).join('');svg.innerHTML=`<defs><marker id="st-live-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#60a5fa"/></marker></defs><g id="st-live-world" transform="translate(${t.x} ${t.y}) scale(${t.scale})">${bands}<g class="st-live-edges">${paths}</g><g class="st-live-nodes">${nodes.map(liveNodeMarkup).join('')}</g></g>`;$('#st-live-count').textContent=`${nodes.length} devices · ${S.live.mapping.physical_links} physical links · ${S.live.mapping.port_channels||0} port-channels · ${S.live.mapping.confirmed_links} confirmed · ${S.live.mapping.unverified_links} unverified · ${S.live.mapping.conflict_links} conflicts · ${liveDisplayLinks().filter(l=>l.logical_observation).length} logical observations (unverified)`;const mini=$('#st-live-minimap');if(mini){const b=liveBounds();mini.setAttribute('viewBox',`${b.x} ${b.y} ${b.w} ${b.h}`);mini.innerHTML=edges.map(e=>{const a=S.live.positions[e.a],z=S.live.positions[e.b];return a&&z?`<line x1="${a.x+95}" y1="${a.y+48}" x2="${z.x+95}" y2="${z.y+48}" stroke="#3979ac" stroke-width="5"/>`:''}).join('')+nodes.map(n=>{const p=S.live.positions[n.id];return p?`<rect x="${p.x}" y="${p.y}" width="190" height="96" rx="8" fill="${Number(n.device_id)===Number(S.live.selectedDevice)?'#37c5ff':'#235b8d'}"/>`:''}).join('')}const zoom=$('#st-live-zoom');if(zoom)zoom.textContent=Math.round(t.scale*100)+'%'}
function livePortOverview(){const ports=(S.ports||[]).filter(p=>p.interface_kind==='physical'||p.physical===true);if(!ports.length)return '';return `<section class="st-live-port-overview"><div class="st-live-panel-heading">Observed physical interfaces <small>${ports.length}</small></div><div class="st-live-port-chips">${ports.map(p=>`<button class="st-live-port-chip ${portState(p)} ${S.live.selectedPort===p.if_name?'selected':''}" data-live-port="${esc(p.if_name)}" title="${esc(p.if_name)} · ${esc(portState(p))} · ${esc(speed(p.speed_bps))}" aria-label="Interface ${esc(p.if_name)}">${esc(p.if_name.replace(/^[a-z-]+/i,''))}</button>`).join('')}</div><small>Interface thực từ SNMP · không giả lập mặt trước thiết bị</small></section>`}
function liveSelectedPortDetails(){const p=(S.ports||[]).find(p=>p.if_name===S.live.selectedPort);if(!p)return '';const did=Number(S.live.selectedDevice),link=(S.live.mapping?.links||[]).find(l=>Number(l.source_device_id)===did?portKey(l.source_port)===portKey(p.if_name):Number(l.target_device_id)===did&&portKey(l.target_port)===portKey(p.if_name)),source=link&&Number(link.source_device_id)===did,peer=link&&device(source?link.target_device_id:link.source_device_id);return `<section class="st-live-port-details"><div class="st-live-panel-heading">Selected Port <b>${esc(p.if_name)}</b></div><dl><dt>Status</dt><dd>${esc(portState(p))}</dd><dt>Speed</dt><dd>${esc(speed(p.speed_bps))}</dd><dt>VLAN</dt><dd>${esc(p.annotation?.vlan||'Unknown')}</dd><dt>Connected device</dt><dd>${esc(peer?.name||'Unknown / Unverified')}</dd><dt>Remote interface</dt><dd>${esc(link?(source?link.target_port:link.source_port):'Unknown / Unverified')}</dd><dt>Mapping</dt><dd>${esc(link?.status||'Unknown / Unverified')}</dd><dt>vPC role</dt><dd>${esc(link?.[source?'source_vpc_role':'target_vpc_role']||'Unknown')}</dd><dt>Observed at</dt><dd>${esc(p.last_seen||'Unknown')}</dd></dl></section>`}
function liveShell(){const d=S.live.topology||{nodes:[]};return `<div class="st-live-layout"><main class="st-live-stage"><div class="st-live-toolbar"><select id="st-live-scope" aria-label="Network scope"><option value="all">Entire Network</option></select><input id="st-live-search" placeholder="Search device, IP, port…"><button data-action="live-fit">Fit</button><button data-action="live-zoom-out" aria-label="Zoom out">−</button><span id="st-live-zoom">${Math.round(S.live.transform.scale*100)}%</span><button data-action="live-zoom-in" aria-label="Zoom in">＋</button><button data-action="v2-panel">Properties</button><button class="v2-focus-reset" data-action="v2-show-all" hidden>Show all devices</button><details class="v2-tools"><summary>View &amp; Layout</summary><button data-action="live-layout">Auto Layout</button><button data-action="live-connections">Connections</button><label>Nodes<select data-v2-option="node">${options(['compact','standard','detailed'],v2opt.node)}</select></label><label>Spacing<select data-v2-option="spacing">${options(['compact','balanced','spacious'],v2opt.spacing)}</select></label><label>Direction<select data-v2-option="direction"><option value="tb" ${v2opt.direction==='tb'?'selected':''}>Top → Bottom</option><option value="lr" ${v2opt.direction==='lr'?'selected':''}>Left → Right</option></select></label><label>Node size<select data-v2-option="nodeSize">${options(['0.9','1','1.2','1.5'],v2opt.nodeSize)}</select></label><label>Trace<select data-v2-option="trace">${options(['all','neighbors','uplinks','downlinks'],v2opt.trace)}</select></label><label>Color by<select data-v2-option="color">${options(['topology','verification','speed','type','operational'],v2opt.color)}</select></label><label>Show<select data-v2-option="filter">${options(['all','confirmed','verified','conflicts','stale'],v2opt.filter)}</select></label><label>Group by<select data-v2-option="groupBy">${options(['role','building','floor','department','vlan','subnet','custom_group'],v2opt.groupBy)}</select></label><button data-action="v2-save">Save layout</button><button data-action="v2-reload">Reload saved layout</button><button data-action="v2-undo">Undo layout</button><button data-action="v2-reset">Reset top-down layout</button><button data-action="v2-group">Re-layout selected group</button><button data-action="v2-focus">Focus / neighbors</button><button data-action="v2-show-all">Show all devices</button><button data-v2-toggle="collapsed">Expand / Collapse channels</button><button data-v2-toggle="labels">Interface labels</button><button data-action="fullscreen">Fullscreen</button><button data-action="navigation">Sidebar</button><button data-action="v2-svg">Export SVG</button><button data-action="v2-png">Export PNG</button><button data-action="v2-html">HTML offline</button><button data-action="v2-pdf">PDF documentation</button></details><button data-action="live-refresh" aria-label="Refresh topology" title="Refresh topology">↻</button><div class="st-view-modes"><button data-live-view="logical" class="${S.live.viewMode==='logical'?'active':''}">Logical</button><button data-live-view="physical" class="${S.live.viewMode==='physical'?'active':''}">Physical</button><button data-live-view="hybrid" class="${S.live.viewMode==='hybrid'?'active':''}">Hybrid</button></div></div><div class="v2-view-description st-sr-only" id="st-live-view-description" aria-live="polite"></div><svg id="st-live-canvas" aria-label="IPAM live topology"></svg><button class="st-live-minimap" data-action="live-fit" aria-label="Fit network map"><svg id="st-live-minimap" aria-hidden="true"></svg></button><div class="st-live-legend"><b>Connection evidence</b><span><i style="background:#10b981"></i>Confirmed</span><span><i style="background:#f59e0b"></i>One-sided</span><span><i style="background:#a855f7"></i>Manual · speed unknown</span><span><i style="background:#ef9c16"></i>Port-channel / LACP</span><span><i style="background:#0284c7"></i>Discovery · unverified (dashed)</span><span><i style="background:#ef4444"></i>Conflict</span><span>Thiếu đầu xa: Unknown / Unverified</span></div><div class="st-live-footer"><span id="st-live-count"></span><span>${esc(d.raw_observations||0)} cached LLDP/CDP observations</span></div></main><aside id="st-live-inspector" class="st-live-inspector"></aside></div>`}
async function linkHistory(){const id=S.live.selectedLink;if(!id||id.startsWith('discovered:')||id.startsWith('legacy:'))throw Error('History chỉ có cho manual mapping đã lưu trong Studio');const result=await request('/connections/'+encodeURIComponent(id)+'/history');const rows=result.history||[];dialog('Mapping history',`<div class="st-scroll">${rows.map(r=>`<article class="st-history-row"><b>${esc(r.action)}</b> · ${esc(r.actor)}<small>${esc(r.created_at)}</small><pre>${esc(JSON.stringify(r.after_state||r.before_state||{},null,2))}</pre></article>`).join('')||'<p>No saved changes.</p>'}</div>`)}
function liveInspector(){if(typeof IPAMTopologyV2!=='undefined')root?.querySelector('.st-live-layout')?.classList.toggle('v2-panel-open',v2opt.panel);const el=$('#st-live-inspector');if(!el)return;const tab=S.live.panel||'ports',dev=device(S.live.selectedDevice),related=(S.live.mapping?.links||[]).filter(l=>Number(l.source_device_id)===Number(S.live.selectedDevice)||Number(l.target_device_id)===Number(S.live.selectedDevice));let body='';if(tab==='ports'&&dev){body=`<div class="st-live-device-card"><svg class="st-live-identity-icon" viewBox="30 0 140 45" aria-hidden="true">${liveDeviceGlyph(dev)}</svg><b>${esc(dev.name)}</b><span>${esc(dev.status||'Unknown')}</span><small>${esc(dev.device_type)} · ${esc(dev.management_ip)}</small></div>${livePortOverview()}<div class="st-live-port-search"><input id="st-live-port-search" placeholder="Tìm interface…"><select id="st-live-port-state">${options(['all','up','down','unknown'],'all')}</select></div><div class="st-live-port-table-head"><span>Port</span><span>Status</span><span>Speed</span><span>VLAN</span><span>Connected To</span></div><div class="st-live-port-list">${(S.ports||[]).map(p=>{const l=related.find(x=>Number(x.source_device_id)===Number(dev.id)?portKey(x.source_port)===portKey(p.if_name):portKey(x.target_port)===portKey(p.if_name)),isSource=l&&Number(l.source_device_id)===Number(dev.id),peer=l&&device(isSource?l.target_device_id:l.source_device_id),remote=l&&(isSource?l.target_port:l.source_port),state=portState(p);return `<button class="st-live-port ${S.live.selectedPort===p.if_name?'selected':''}" data-live-port="${esc(p.if_name)}"><span><b>${esc(p.if_name)}</b><small>${esc(p.if_descr||'')}</small></span><i class="${state.toLowerCase().includes('up')?'up':''}">${esc(state)}</i><span>${esc(speed(p.speed_bps))}</span><span>${esc(p.annotation?.vlan||'—')}</span><span>${esc(l?`${peer?.name||'Unknown'} · ${remote}`:'Unknown / Unverified')}</span></button>`}).join('')}</div>${liveSelectedPortDetails()}`}else if(tab==='device'&&dev){body=`<div class="st-live-device-card"><svg class="st-live-identity-icon" viewBox="30 0 140 45" aria-hidden="true">${liveDeviceGlyph(dev)}</svg><b>${esc(dev.name)}</b><span>${esc(dev.status||'Unknown')}</span><small>${esc(dev.vendor||'')} · ${esc(dev.device_type)} · ${esc(dev.management_ip)}</small></div><dl><dt>Model</dt><dd>${esc(dev.metadata?.model||'Unknown')}</dd><dt>Serial</dt><dd>${esc(dev.serial_number||'Unknown')}</dd><dt>Last discovery</dt><dd>${esc(dev.last_discovery||'Unknown')}</dd><dt>Interfaces</dt><dd>${S.ports.length} observed</dd><dt>Mapped links</dt><dd>${related.length}</dd></dl>`}else{const link=liveDisplayLinks().find(l=>l.id===S.live.selectedLink);body=link?`<div class="st-live-device-card"><b>${esc(device(link.source_device_id)?.name||'Unknown')} ${esc(link.source_port)} ↔ ${esc(device(link.target_device_id)?.name||'Unknown')} ${esc(link.target_port)}</b><span>${esc(link.status)}</span><small>${esc(link.protocols?.join(' / ')||link.source||'')} · ${esc(link.last_seen||'No observation time')}</small></div><dl><dt>Link type</dt><dd>${esc(link.link_type||'Physical')}</dd><dt>vPC evidence</dt><dd>${esc(link.source_vpc_role||'Unknown')} ↔ ${esc(link.target_vpc_role||'Unknown')}</dd><dt>Endpoint status</dt><dd>${esc(link.source_oper_status||'Unknown')} ↔ ${esc(link.target_oper_status||'Unknown')}</dd><dt>Speed</dt><dd>${esc(speed(link.source_speed_bps))} ↔ ${esc(speed(link.target_speed_bps))}</dd><dt>Evidence</dt><dd>${esc(link.evidence_count||link.discovery_evidence?.length||0)} observations</dd><dt>Discovery</dt><dd>${esc(link.logical_observation?'Device-level discovery only; physical ports are not verified':link.discovery_agrees?'Matches exact endpoints':link.discovery_conflict?'Conflicts with saved mapping':'No exact reciprocal confirmation')}</dd><dt>Port-channel</dt><dd>${esc(link.port_channel||link.metadata?.port_channel||'Unknown')}</dd>${link.link_type==='PORT_CHANNEL'?`<dt>Source members</dt><dd>${esc((link.source_members||[]).map(x=>x.member_if_name).join(', ')||'Unknown / no IF-MIB membership')}</dd><dt>Target members</dt><dd>${esc((link.target_members||[]).map(x=>x.member_if_name).join(', ')||'Unknown / no IF-MIB membership')}</dd>`:''}</dl>${link.id.startsWith('discovered:')||link.id.startsWith('legacy:')?'<p class="st-muted">Discovery/legacy evidence; no saved mapping overwrite.</p>':`<button data-edit-link="${esc(link.id)}">Edit mapping</button><button data-action="link-history">View history</button>`}`:'<p class="st-muted">Chọn một link trên topology để xem đối chiếu hai đầu.</p>'}el.innerHTML=`<div class="st-live-inspector-tabs"><button data-live-panel="device" class="${tab==='device'?'active':''}">Device Info</button><button data-live-panel="ports" class="${tab==='ports'?'active':''}">Port Mapping</button><button data-live-panel="link" class="${tab==='link'?'active':''}">Link Info</button></div><div class="st-live-inspector-body">${body||'<p class="st-muted">Chọn thiết bị để xem interface và kết nối.</p>'}</div>`;const f=$('#st-live-port-search'),state=$('#st-live-port-state');if(f)f.oninput=()=>{const q=f.value.toLowerCase();root.querySelectorAll('[data-live-port]').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))};if(state)state.onchange=()=>root.querySelectorAll('[data-live-port]').forEach(x=>{const text=x.querySelector('i')?.textContent.toLowerCase()||'';x.hidden=state.value!=='all'&&(state.value==='up'?!text.includes('up'):state.value==='down'?!text.includes('down'):text==='up'||text.includes('down'))});if(typeof IPAMTopologyV2!=='undefined')v2InspectorExtras()}
function renderLive(){const content=$('#st-content');if(liveWorkspace&&S.live.topology){content.replaceChildren(liveWorkspace);liveGraph();if(S.live.inspectorDirty){liveInspector();S.live.inspectorDirty=false}v2Transform();return}if(!S.live.topology){content.innerHTML='<div class="st-loading">Đang tải topology discovery và evidence LLDP/CDP…</div>';return}content.innerHTML=liveShell();liveWorkspace=content.querySelector('.st-live-layout');liveGraph();liveInspector();S.live.inspectorDirty=false;bindLiveCanvas();if(typeof IPAMTopologyV2!=='undefined')v2BindCanvas();if(!S.live.hasViewport){liveFit();S.live.hasViewport=true}else v2Transform()}
function bindLiveCanvas(){const svg=$('#st-live-canvas');if(!svg||svg.dataset.bound)return;svg.dataset.bound='1';let drag=null;svg.addEventListener('click',async e=>{const port=e.target.closest('[data-live-port]');if(port){S.live.selectedPort=port.dataset.livePort;const d=S.inventory.find(x=>Number(x.id)===Number(S.live.selectedDevice));const found=(S.live.mapping.links||[]).find(l=>Number(l.source_device_id)===Number(d?.id)?portKey(l.source_port)===portKey(port.dataset.livePort):Number(l.target_device_id)===Number(d?.id)&&portKey(l.target_port)===portKey(port.dataset.livePort));if(found)S.live.selectedLink=found.id;liveGraph();liveInspector();return}const edge=e.target.closest('[data-live-edge]');if(edge){const group=(typeof IPAMTopologyV2!=='undefined'?v2edges():liveEdges()).find(x=>x.id===edge.dataset.liveEdge);S.live.selectedLink=group?.link?.id||group?.links?.[0]?.id||null;if(group?.id?.startsWith('bundle:'))v2opt.collapsed=false;S.live.panel='link';v2opt.panel=true;liveGraph();liveInspector();return}const nodeEl=e.target.closest('[data-live-node]');if(nodeEl){const n=S.live.topology.nodes.find(x=>x.id===nodeEl.dataset.liveNode);if(n?.device_id){S.live.selectedDevice=Number(n.device_id);S.live.selectedPort=null;S.live.panel='device';v2opt.panel=true;const result=await request('/inventory/'+n.device_id+'/ports');S.ports=result.ports;S.portProfile=result.hardware_profile;liveInspector();liveGraph()}return}});svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-live-node],[data-live-edge]'))return;drag={x:e.clientX,y:e.clientY,transform:{...S.live.transform}};svg.setPointerCapture(e.pointerId)});svg.addEventListener('pointermove',e=>{if(!drag)return;S.live.transform.x=drag.transform.x+e.clientX-drag.x;S.live.transform.y=drag.transform.y+e.clientY-drag.y;typeof IPAMTopologyV2!=='undefined'?v2Transform():liveGraph()});svg.addEventListener('pointerup',()=>{drag=null});svg.addEventListener('wheel',e=>{e.preventDefault();const k=e.deltaY<0?1.1:1/1.1;S.live.transform.scale=Math.max(.15,Math.min(2,S.live.transform.scale*k));typeof IPAMTopologyV2!=='undefined'?v2Transform():liveGraph()},{passive:false})}
function work(){return `<div class="st-toolbar"><select id="st-diagram" aria-label="Diagram"></select><button data-action="browse">Browse</button><button data-action="new">＋ New</button><button data-action="save" class="st-primary">Save</button><button id="st-undo" data-action="undo" title="Undo">↶</button><button id="st-redo" data-action="redo" title="Redo">↷</button><select id="st-layout" aria-label="Layout">${options(['top-bottom','left-right','compact','balanced','spacious','manual'],S.layout==='hierarchical'?'top-bottom':S.layout)}</select><button data-action="layout">Auto layout</button>${S.advanced?`<div class="st-view-modes" role="group" aria-label="Topology view">${[['hierarchical','Logical'],['physical','Physical'],['hybrid','Hybrid']].map(([v,label])=>`<button type="button" data-view-mode="${v}" class="${S.viewMode===v?'active':''}" aria-pressed="${S.viewMode===v}">${label}</button>`).join('')}</div><button data-action="edge-grouping" class="${S.edgeGrouping?'active':''}" title="Group members by port-channel; click a group edge to expand">Port-channel</button><button data-action="labels" class="${S.showLabels?'active':''}">Labels</button><select id="st-color-by" aria-label="Color links by">${options(['type','bandwidth','vlan','status'],S.colorBy)}</select>`:''}<button data-action="fit">Fit</button><button data-action="zoom-out">−</button><span id="st-zoom">100%</span><button data-action="zoom-in">＋</button><button data-action="grid">Grid</button><details><summary>More</summary><div class="st-actions"><button data-action="rename">Rename</button><button data-action="duplicate">Duplicate</button><button data-action="archive">Archive</button><button data-action="revisions">Revisions</button><button data-action="align">Align</button><button data-action="group">Group</button><button data-action="from-discovery">From IPAM topology</button><button data-action="import-diagram">Import JSON</button><button data-action="connections">Connections</button><button data-action="fullscreen">Fullscreen</button></div></details></div><div class="st-work"><aside class="st-library"><h3>Device Library</h3><input id="st-library-search" placeholder="Search inventory…" aria-label="Search inventory"><div class="st-category">Shared network devices</div><div id="st-devices"></div><div class="st-category">Network groups & custom</div><select id="st-kind" aria-label="Custom device type">${options(kinds,'Server')}</select><button data-action="add-custom" style="margin-top:8px">＋ Add device</button></aside><div class="st-stage"><svg id="st-canvas" class="st-canvas ${S.grid?'st-grid':''}" aria-label="Topology canvas"></svg><div class="st-empty" id="st-empty"><h3>${S.diagram?'Start designing your network':'Chọn hoặc tạo sơ đồ'}</h3><p>Kéo thiết bị từ Inventory vào canvas.<br>Bấm chấm xanh trên node để nối thiết bị.</p></div></div><aside class="st-properties" id="st-properties"></aside></div><div class="st-status"><span id="st-save-status">${S.diagram?'Saved · r'+S.diagram.revision:'Ready'}</span><span id="st-count"></span></div>`}
