 if(!link.dataset.studioTabLink){link.dataset.studioTabLink='true';link.addEventListener('click',e=>{if(location.hash==='#topology'&&root){e.preventDefault();e.stopImmediatePropagation();if(S.screen!=='topology')switchMode('topology').catch(fail)}},true)}
