function render(){if(!root)return;const existing=root.querySelector('.st-live-layout');if(existing)liveWorkspace=existing;syncStudioNav();syncStudioHeader();root.innerHTML=`<div class="st-head"><button class="st-mobile-nav" data-action="navigation">☰ IPAM</button><div><div class="st-muted">NETWORK / IPAM</div><h2>Network Topology Studio</h2><div class="st-muted">Live inventory · LLDP/CDP evidence · Port-to-port mapping</div></div><button data-action="legacy">Legacy topology</button></div><nav class="st-actions st-document-tabs"><button data-mode="topology" class="${S.screen==='topology'?'active':''}">Network Topology</button><button data-mode="ports" class="${S.screen==='ports'?'active':''}">Port Mapping</button><button data-mode="servers" class="${S.screen==='servers'?'active':''}">Server Connection</button><button data-mode="ha" class="${S.screen==='ha'?'active':''}">HA Management</button><button data-mode="connections" class="${S.screen==='connections'?'active':''}">Connections</button><button data-mode="diagrams" class="${S.screen==='diagrams'?'active':''}">Diagrams</button><button data-mode="export" class="${S.screen==='export'?'active':''}">Export</button></nav><div id="st-content"></div><dialog id="st-dialog"></dialog>`;if(S.screen==='topology'||S.screen==='logical'||S.screen==='physical'){renderLive()}else if(S.screen==='diagrams'){diagramOptions();library();$('#st-content').innerHTML=work();diagramOptions();library();graph();bindCanvas()}else if(S.screen==='ports')renderPorts();else if(S.screen==='servers')renderServers();else if(S.screen==='ha')renderHA();else if(S.screen==='connections')renderConnectionManager();else renderExport()}
async function refresh(full=true){const seq=++refreshSeq;const [health,inv,ds,con]=await Promise.all([request('/health'),request('/inventory'),request('/diagrams'),full?request('/connections'):Promise.resolve(null)]);if(seq!==refreshSeq)return;S.advanced=!!health.advanced_views;S.inventory=inv.devices;if(con){S.connections=con;connectionsReady=true}S.diagrams=ds;S.ready=true}
async function switchMode(mode){if(S.switching)return;S.switching=true;root.setAttribute('aria-busy','true');try{if(S.dirty)await save();S.screen=['logical','physical'].includes(mode)?'topology':mode;S.port=null;v2opt.focus=false;if(mode==='topology'||mode==='logical'||mode==='physical'){if(Date.now()-liveLoadedAt>15000)await loadLiveTopology();if(mode!=='topology')S.live.viewMode=mode}else if(mode==='ports'){if(!connectionsReady)await refresh();S.mode='ports'}else if(mode==='export'){if(!connectionsReady)await refresh();S.mode='export'}else if(mode==='diagrams'){if(!connectionsReady)await refresh();if(!['logical','physical'].includes(S.mode))S.mode='logical';if(S.diagram?.kind!==S.mode){S.diagram=null;const d=S.diagrams.find(d=>d.kind===S.mode);if(d)await openDiagram(d.id,false)}}render()}finally{S.switching=false;root.removeAttribute('aria-busy')}}
async function openDiagram(id,paint=true){if(S.dirty)await save();S.diagram=await request('/diagrams/'+encodeURIComponent(id));S.mode=S.diagram.kind;S.blocked=false;S.selected.clear();S.edge=null;S.undo=[];S.redo=[];S.view={x:40,y:40,zoom:1,...S.diagram.document.viewport};S.grid=S.view.grid!==false;S.layout=S.view.layout||'hierarchical';S.viewMode=S.advanced&&['hierarchical','physical','hybrid'].includes(S.view.view_mode)?S.view.view_mode:'hybrid';S.showLabels=S.view.show_labels!==false;S.edgeGrouping=!!S.view.edge_grouping;S.colorBy=S.view.color_by||'type';S.expandedGroups.clear();if(paint)render()}
async function save(){clearTimeout(saveTimer);if(!S.dirty||!S.diagram)return;if(S.blocked)throw Error('Save blocked by revision conflict. Reload this diagram.');if(S.saving){await savePromise;if(S.dirty)return save();return}S.saving=true;const id=S.diagram.id,gen=S.generation;note('Saving…');try{savePromise=mutate('PUT','/diagrams/'+id,{title:S.diagram.title,kind:S.diagram.kind,document:clone(doc()),revision:S.diagram.revision});const result=await savePromise;if(S.diagram?.id===id){S.diagram.revision=result.revision;if(gen===S.generation)S.dirty=false;else saveTimer=setTimeout(()=>save().catch(fail),500);note('Saved · r'+result.revision);const d=S.diagrams.find(d=>d.id===id);if(d)Object.assign(d,{title:result.title,revision:result.revision});diagramOptions()}}catch(e){if(e.status===409)S.blocked=true;throw e}finally{S.saving=false}}
function addNode(did,kind,pos){if(!editable()){note('Tạo hoặc chọn sơ đồ trước');return}history();const p=pos||{x:70+(doc().nodes.length%4)*210,y:70+Math.floor(doc().nodes.length/4)*110};doc().nodes.push({id:uid(),device_id:did||null,name:did?undefined:kind,kind:kind||device(did)?.device_type||'Switch',x:p.x,y:p.y,color:'#2563eb'});S.selected=new Set([doc().nodes.at(-1).id]);S.edge=null;graph();dirty()}
function addEdge(from,to){if(from===to)return;if(S.mode==='physical'){const a=node(from),b=node(to);if(!a?.device_id||!b?.device_id){note('Physical mapping requires two shared inventory devices');S.linkStart=null;return}S.linkStart=null;linkDialog(null,{from,to}).catch(fail);return}history();doc().edges.push({id:uid(),source:from,target:to,label:'',style:'orthogonal',link_type:'Layer 2',color:'#7186a4'});S.linkStart=null;graph();dirty()}
function removeSelection(){if(!editable())return;history();doc().nodes=doc().nodes.filter(n=>!S.selected.has(n.id));doc().edges=doc().edges.filter(e=>e.id!==S.edge&&!S.selected.has(e.source)&&!S.selected.has(e.target));S.selected.clear();S.edge=null;graph();dirty()}
function undo(redo=false){if(!editable())return;const from=redo?S.redo:S.undo,to=redo?S.undo:S.redo;if(!from.length)return;to.push(clone(doc()));S.diagram.document=from.pop();S.selected.clear();S.edge=null;graph();dirty()}
function applyLayout(){if(!editable())return;const preset=$('#st-layout')?.value||S.layout;if(preset==='manual')return;history();S.layout=preset;const ns=doc().nodes,edges=doc().edges;if(!ns.length)return;const adjacency=new Map(ns.map(n=>[n.id,new Set()])),degree=new Map(ns.map(n=>[n.id,0]));for(const e of edges){adjacency.get(e.source)?.add(e.target);adjacency.get(e.target)?.add(e.source);degree.set(e.source,(degree.get(e.source)||0)+1);degree.set(e.target,(degree.get(e.target)||0)+1)}const hubs=[...ns].sort((a,b)=>(degree.get(b.id)||0)-(degree.get(a.id)||0)).slice(0,Math.max(1,Math.ceil(ns.length*.08))).map(n=>n.id),dist=new Map(hubs.map(id=>[id,0])),queue=[...hubs];for(let head=0;head<queue.length;head++){const id=queue[head];for(const peer of adjacency.get(id)||[])if(!dist.has(peer)){dist.set(peer,(dist.get(id)||0)+1);queue.push(peer)}}const role=n=>{const d=device(n.device_id),v=`${d?.metadata?.role||''} ${d?.metadata?.function||''} ${n.kind||''} ${d?.device_type||''} ${d?.name||''}`.toLowerCase();if(/internet|wan|cloud/.test(v))return 0;if(/firewall|security|sophos/.test(v))return 1;if(/core/.test(v))return 2;if(/distribution|dist/.test(v))return 3;if(/access/.test(v))return 4;if(/server|storage|virtualization/.test(v))return 5;return null};const ranks=new Map(ns.map(n=>[n.id,role(n)]));for(const n of ns)if(ranks.get(n.id)===null)ranks.set(n.id,Math.min(5,dist.get(n.id)??2));if(![...ns].some(n=>role(n)!==null)&&hubs.length===1)ranks.set(hubs[0],0);const cols=preset==='compact'?210:preset==='spacious'?330:preset==='left-right'?250:230,rows=preset==='compact'?112:preset==='spacious'?230:preset==='balanced'?180:145,maxColumns=Math.max(1,Math.floor(1400/cols)),buckets=new Map();for(const n of ns){const r=ranks.get(n.id)??0;if(!buckets.has(r))buckets.set(r,[]);buckets.get(r).push(n)}for(const [rank,items] of buckets){items.sort((a,b)=>(a.group||'').localeCompare(b.group||'')||nodeName(a).localeCompare(nodeName(b)));items.forEach((n,i)=>{if(preset==='top-bottom'||preset==='balanced'||preset==='compact'||preset==='spacious'){n.x=100+(i%maxColumns)*cols;n.y=80+rank*rows+Math.floor(i/maxColumns)*rows}else{n.x=100+rank*cols;n.y=80+i*rows}})}doc().viewport={...doc().viewport,layout:preset,manual_positions:false};S.view.manual_positions=false;graph();fit();queueView()}
function layout(){if(!editable())return;if(doc().viewport?.manual_positions){dialog('Replace manual positions?','<p>Auto Layout will reposition devices in this diagram. Your current positions remain available with Undo.</p>',async()=>applyLayout());return}applyLayout()}
function setViewMode(mode){if(!S.advanced||!['hierarchical','physical','hybrid'].includes(mode))return;S.viewMode=mode;S.expandedGroups.clear();doc().viewport={...doc().viewport,view_mode:mode};graph();root.querySelectorAll('[data-view-mode]').forEach(b=>{const active=b.dataset.viewMode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});queueView()}
