// V2 uses cached inventory and mapping records; presentation never writes physical evidence.
let v2RenderKey=null,v2worker=null,v2workerResult=null,v2workerPending=null;
let v2opt={spacing:'balanced',direction:'tb',node:'standard',color:'topology',filter:'all',groupBy:'role',trace:'all',nodeSize:'1',panel:false,labels:false,collapsed:false},v2geometry=null,v2routes=[],v2layoutUndo=[],v2manual=false,v2saved=null;
try{Object.assign(v2opt,JSON.parse(localStorage.getItem('ipam-topology-v2-options')||'{}'))}catch{}
