function v2UndoLayout(){const state=v2layoutUndo.pop();if(!state){note('No layout change to undo. Use Reload saved layout or Reset top-down layout.');return}S.live.positions=clone(state.positions||state);if(state.options)Object.assign(v2opt,state.options);v2manual=state.manual??true;v2geometry={positions:S.live.positions};v2RenderKey=null;v2SyncLayoutOptions();liveGraph();liveFit()}
function v2SavedLayoutOptions(document){const vp=document.viewport||{};if(vp.presentation_theme==='pastel-v6'&&['topology','verification','speed','type','operational'].includes(vp.color_by))v2opt.color=vp.color_by;const saved=vp.layout_options||(vp.direction?{direction:vp.direction,spacing:vp.layout,node:vp.node_style,nodeSize:vp.node_size,groupBy:vp.group_by}:null);if(saved){for(const k of ['direction','spacing','node','nodeSize','groupBy'])if(saved[k]!=null)v2opt[k]=saved[k]}else{const ranks=IPAMTopologyV2.roles(v2nodes(),liveDisplayLinks().map(l=>({a:'d:'+l.source_device_id,b:'d:'+l.target_device_id}))),groups=new Map();for(const n of document.nodes||[]){const rank=ranks.get(n.id);if(rank==null)continue;if(!groups.has(rank))groups.set(rank,[]);groups.get(rank).push(n)}const ordered=[...groups].sort((a,b)=>a[0]-b[0]);const center=ns=>({x:ns.reduce((a,n)=>a+n.x,0)/ns.length,y:ns.reduce((a,n)=>a+n.y,0)/ns.length});if(ordered.length>1){const a=center(ordered[0][1]),b=center(ordered.at(-1)[1]);v2opt.direction=Math.abs(b.x-a.x)>Math.abs(b.y-a.y)?'lr':'tb'}if(['compact','balanced','spacious'].includes(document.viewport?.layout))v2opt.spacing=document.viewport.layout}v2SyncLayoutOptions()}
