function v2nodes(){return (S.live.topology?.nodes||[]).filter(n=>n.device_id!=null).map(n=>({...n,...device(n.device_id),id:n.id,device_id:n.device_id}))}
function v2size(){const scale=Number(v2opt.nodeSize)||1,size=v2opt.node==='compact'?{width:200,height:84}:v2opt.node==='detailed'?{width:250,height:154}:{width:230,height:116};return {width:size.width*scale,height:size.height*scale}}
function v2layout(force=false,previous=null){if(v2manual&&!force){const missing=v2nodes().filter(n=>!S.live.positions[n.id]);let x=Math.max(0,...Object.values(S.live.positions).map(p=>p.x))+300;for(const n of missing){const peer=n.ha_cluster_id?v2nodes().find(p=>p.id!==n.id&&p.ha_cluster_id===n.ha_cluster_id&&S.live.positions[p.id]):null;if(peer){const p=S.live.positions[peer.id],size=v2size();let px=p.x+size.width+50;while(Object.values(S.live.positions).some(q=>Math.abs(q.x-px)<size.width&&Math.abs(q.y-p.y)<size.height))px+=size.width+50;S.live.positions[n.id]={x:px,y:p.y}}else{S.live.positions[n.id]={x,y:70};x+=300}}return;}v2PushLayout(previous||v2CaptureLayout());const nodes=v2nodes(),links=liveDisplayLinks().map(l=>({a:'d:'+l.source_device_id,b:'d:'+l.target_device_id}));v2geometry=IPAMTopologyV2.layout(nodes,links,{...v2opt,...v2size()});S.live.positions=v2geometry.positions;v2manual=false}
function v2edges(){let edges=liveEdges();if(v2opt.trace!=='all'){const id='d:'+S.live.selectedDevice,ranks=IPAMTopologyV2.roles(v2nodes(),liveDisplayLinks().map(l=>({a:'d:'+l.source_device_id,b:'d:'+l.target_device_id})));edges=edges.filter(e=>{if(e.a!==id&&e.b!==id)return false;const peer=e.a===id?e.b:e.a;return v2opt.trace==='neighbors'||(v2opt.trace==='uplinks'?ranks.get(peer)<=ranks.get(id):ranks.get(peer)>ranks.get(id))})}if(v2opt.filter==='confirmed')edges=edges.filter(e=>((e.link||e.links?.[0])?.verification_status||(e.link||e.links?.[0])?.status)==='CONFIRMED');if(v2opt.filter==='verified')edges=edges.filter(e=>['CONFIRMED','VERIFIED'].includes((e.link||e.links?.[0])?.status));if(v2opt.filter==='conflicts')edges=edges.filter(e=>(e.link||e.links?.[0])?.status==='CONFLICT');if(v2opt.filter==='stale')edges=edges.filter(e=>(e.link||e.links?.[0])?.freshness==='STALE');if(v2opt.collapsed&&S.live.viewMode==='hybrid'){const groups=new Map(),out=[];for(const e of edges){const l=e.link;if(l?.port_channel&&l.link_type==='PHYSICAL'){const k=[e.a,e.b].sort().join('|')+'|'+l.port_channel;if(!groups.has(k)){groups.set(k,{...e,links:[],link:null,id:'bundle:'+k});out.push(groups.get(k))}groups.get(k).links.push(l)}else out.push(e)}edges=out}return edges}
