async function init(){const page=$('#page-topology');if(!page)return;let old=$('#studio-legacy');if(!old){old=document.createElement('div');old.id='studio-legacy';while(page.firstChild)old.append(page.firstChild);old.hidden=true;const back=document.createElement('button');back.className='btn';back.textContent='← Network Topology Studio';back.onclick=()=>{old.hidden=true;root.hidden=false};old.prepend(back);page.append(old)}root=document.createElement('section');root.id='studio';page.prepend(root);bind();bindLiveControls();render();await initializeTopology()}
